import{_ as r,o as l,c as t,a2 as e}from"./chunks/framework.BV21bweQ.js";const p=JSON.parse('{"title":"精灵族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/精灵族.md","filePath":"表层/种族/精灵族.md","lastUpdated":1787066340000}'),o={name:"表层/种族/精灵族.md"};function i(n,a,s,h,d,c){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="精灵族" tabindex="-1">精灵族 <a class="header-anchor" href="#精灵族" aria-label="Permalink to &quot;精灵族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>精灵族是世界观中<strong>唯一长得像人的种族</strong>，神秘而独特，族群数量少但分布广。上一次大变故后，绝大多数精灵选择隐居，不再参与时事，变故的具体原因成谜。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>外形</strong>：是唯一长得像人的种族，唯一不同于常人的特征是尖耳朵。</li><li><strong>发色瞳色</strong>：白发金瞳。</li><li><strong>服饰</strong>：平日身穿白袍配金色条纹。</li><li><strong>法杖</strong>：手持一柄古朴的木制法杖。</li></ul><p>整体形象&quot;看起来&quot;符合精灵的刻板印象。</p><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><ul><li><strong>神秘</strong>：族群数量少但分布广，关于精灵的记载稀少，多数传闻语焉不详。</li><li><strong>避世</strong>：上一次大变故后，大多数精灵选择隐居，不再参与时事，变故原因成谜。</li></ul><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><p>精灵族经历了一次鲜为人知的大变故。变故之后，大多数精灵选择隐居，不再参与时事。变故的具体原因至今没有明确记载，是大陆上的一个谜团。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>目前已知的精灵族个体之一是红星孤儿院的<strong>副院长艾莉芙</strong>：</p><ul><li><strong>外貌</strong>：白发金瞳，白袍配金色条纹，手持古朴的木制法杖。</li><li><strong>性格</strong>：性格偏冷、生人勿近，但对孤儿院的孩子们温和包容。</li><li><strong>日常表现</strong>：负责孤儿院的日常管理，从容镇定，观察敏锐。</li></ul><p>详见 <a href="./../../中层/人物/艾莉芙" class="layer-link" data-layer="中层">艾莉芙</a>。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>精灵族的真实来历与上次大变故的真相不属表层认知。</p></blockquote><ul><li><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></li><li><a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></li><li><a href="./../../中层/世界/特殊地点" class="layer-link" data-layer="中层">特殊地点</a></li><li><a href="./../../中层/人物/艾莉芙" class="layer-link" data-layer="中层">艾莉芙</a></li></ul><hr>',23)])])}const _=r(o,[["render",i]]);export{p as __pageData,_ as default};
